<?php
if (!defined('ROUTER_LOADED')) { http_response_code(403); exit('Accès direct interdit.'); }
if (!userCan($user, 'stock.mouvements') && !userCan($user, 'flux.view')) { http_response_code(403); echo '<div class="rounded-md border border-red-200 bg-red-50 p-4 text-red-700">Accès refusé.</div>'; return; }
require_once __DIR__ . '/../../api/database.php'; require_once __DIR__ . '/_inventory.php';
$db=Database::getInstance(); $role=$user['role_system']; $search=trim((string)($_GET['q']??'')); $type=(string)($_GET['type']??'');
if (!in_array($type,['entree','sortie','correction'],true)) $type='';
$conditions=['1 = 1']; $params=[];
if($search!==''){ $conditions[]='(product_name LIKE ? OR reference LIKE ? OR operator LIKE ?)'; $p='%'.$search.'%'; array_push($params,$p,$p,$p); }
if($type!==''){ $conditions[]='movement_type = ?'; $params[]=$type; }
$where='WHERE '.implode(' AND ',$conditions); $total=(int)$db->fetchColumn("SELECT COUNT(*) FROM stock_movements $where",$params); $page=max(1,(int)($_GET['page']??1)); $perPage=25; $pages=max(1,(int)ceil($total/$perPage)); $page=min($page,$pages); $offset=($page-1)*$perPage;
$movements=$db->fetchAll("SELECT product_name,movement_type,quantity,quantity_before,quantity_after,unit_cost,total_amount,reference,reason,operator,created_at FROM stock_movements $where ORDER BY id DESC LIMIT $perPage OFFSET $offset",$params);
$flash=$_SESSION['flash_message']??null; unset($_SESSION['flash_message']);
$pageUrl=static fn(int $target):string=>app_route_url('stock/mouvements',$role).'?'.http_build_query(['q'=>$search,'type'=>$type,'page'=>$target]);
?>
<section class="space-y-5"><header class="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><p class="text-sm font-semibold text-blue-800">Traçabilité</p><h1 class="mt-1 text-2xl font-bold text-slate-900">Mouvements de stock</h1><p class="mt-1 text-sm text-slate-600"><?= number_format($total,0,',',' ') ?> mouvement(s)</p></div><div class="flex gap-2"><?php if(userCan($user,'flux.entrees')):?><a href="<?=inventoryEscape(app_route_url('stock/entrees'))?>" class="rounded-md border px-3 py-2 text-sm">Nouvelle entrée</a><?php endif;?><?php if(userCan($user,'flux.sorties')):?><a href="<?=inventoryEscape(app_route_url('stock/sorties'))?>" class="rounded-md bg-rose-700 px-3 py-2 text-sm font-medium text-white">Nouvelle sortie</a><?php endif;?></div></header>
<?php if($flash):?><div role="status" class="rounded-md border px-4 py-3 text-sm <?=($flash['type']??'')==='success'?'border-green-200 bg-green-50 text-green-800':'border-red-200 bg-red-50 text-red-800'?>"><?=inventoryEscape($flash['text']??'')?></div><?php endif;?>
<form method="get" action="<?=inventoryEscape(app_url('router.php'))?>" class="grid gap-3 rounded-md border bg-white p-4 sm:grid-cols-[minmax(12rem,1fr)_12rem_auto_auto] sm:items-end"><input type="hidden" name="route" value="<?=inventoryEscape($role.'/stock/mouvements')?>"><label class="space-y-1 text-sm font-medium">Recherche<input name="q" value="<?=inventoryEscape($search)?>" placeholder="Produit, référence, opérateur" class="w-full rounded-md border px-3 py-2 font-normal"></label><label class="space-y-1 text-sm font-medium">Type<select name="type" class="w-full rounded-md border bg-white px-3 py-2 font-normal"><option value="">Tous</option><?php foreach(['entree'=>'Entrée','sortie'=>'Sortie','correction'=>'Correction'] as $key=>$label):?><option value="<?=$key?>" <?=$type===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><button class="rounded-md border px-4 py-2 text-sm">Filtrer</button><?php if($search!==''||$type!==''):?><a href="<?=inventoryEscape(app_route_url('stock/mouvements'))?>" class="px-3 py-2 text-sm text-slate-600">Effacer</a><?php endif;?></form>
<div class="overflow-x-auto rounded-md border bg-white"><table class="min-w-full divide-y text-sm"><thead class="bg-slate-50 text-left text-xs uppercase text-slate-500"><tr><th class="px-4 py-3">Date</th><th class="px-4 py-3">Produit</th><th class="px-4 py-3">Type</th><th class="px-4 py-3 text-right">Quantité</th><th class="px-4 py-3">Stock avant → après</th><th class="px-4 py-3">Référence / motif</th><th class="px-4 py-3">Opérateur</th></tr></thead><tbody class="divide-y divide-slate-100">
<?php if(!$movements):?><tr><td colspan="7" class="px-4 py-12 text-center text-slate-500">Aucun mouvement pour ces critères.</td></tr><?php else:foreach($movements as $movement): $labels=['entree'=>'Entrée','sortie'=>'Sortie','correction'=>'Correction'];?><tr class="align-top hover:bg-slate-50"><td class="whitespace-nowrap px-4 py-3 text-slate-600"><?=inventoryEscape(date('d/m/Y H:i',strtotime($movement['created_at'])))?></td><td class="px-4 py-3 font-medium"><?=inventoryEscape($movement['product_name'])?></td><td class="px-4 py-3"><span class="rounded-full px-2 py-1 text-xs <?= $movement['movement_type']==='entree'?'bg-green-100 text-green-800':($movement['movement_type']==='sortie'?'bg-rose-100 text-rose-800':'bg-amber-100 text-amber-800')?>"><?=inventoryEscape($labels[$movement['movement_type']]??$movement['movement_type'])?></span></td><td class="px-4 py-3 text-right font-medium"><?=number_format((float)$movement['quantity'],2,',',' ')?></td><td class="px-4 py-3 text-slate-600"><?=number_format((float)$movement['quantity_before'],2,',',' ')?> → <?=number_format((float)$movement['quantity_after'],2,',',' ')?></td><td class="max-w-xs px-4 py-3 text-slate-600"><?php if($movement['reference']):?><div><?=inventoryEscape($movement['reference'])?></div><?php endif;?><div class="text-xs"><?=inventoryEscape($movement['reason']?:'—')?></div></td><td class="px-4 py-3"><?=inventoryEscape($movement['operator'])?></td></tr><?php endforeach;endif;?>
</tbody></table></div>
<?php if($pages>1):?><nav class="flex items-center justify-between"><span class="text-sm text-slate-600">Page <?=$page?> sur <?=$pages?></span><div class="flex gap-2"><?php if($page>1):?><a href="<?=inventoryEscape($pageUrl($page-1))?>" class="rounded border px-3 py-2 text-sm">Précédent</a><?php endif;?><?php if($page<$pages):?><a href="<?=inventoryEscape($pageUrl($page+1))?>" class="rounded border px-3 py-2 text-sm">Suivant</a><?php endif;?></div></nav><?php endif;?></section>